let frontendPreviewListener=null;
function stopFrontendPreview(){if(frontendPreviewListener){window.removeEventListener('message',frontendPreviewListener);frontendPreviewListener=null;}const frame=document.getElementById('frontend-preview');if(frame)frame.remove();}
function frontendDraftKey(){return 'web-talim:frontend:'+activeData().assignment.draftId;}
function renderFrontendAssignment(data){const a=data.assignment,panel=document.createElement('section');panel.id='panel5';panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab5');
 panel.innerHTML=`${a.stage?`<p class="notice">Bosqich: ${frontendEscape(a.stage)}</p>`:''}${a.prerequisite?`<h3>Tayanch bilimlar</h3><p>${frontendEscape(a.prerequisite)}</p>`:''}${a.teaching?`<h3>Avval tushunib oling</h3><p>${frontendEscape(a.teaching)}</p>`:''}<h2>Mavzuga oid amaliy topshiriq</h2><p>${frontendEscape(a.task)}</p><h3>Tekshirish mezonlari</h3><ol>${a.criteria.map(x=>`<li>${frontendEscape(x)}</li>`).join('')}</ol><details><summary>Namuna kodi va kutiladigan natija</summary><pre class="lesson-code"><code>${frontendEscape(a.code)}</code></pre><p>${frontendEscape(a.expected)}</p></details>`;
 if(['web','html','css'].includes(a.mode))panel.innerHTML+=`<p class="muted">${a.mode==='html'?'Faqat HTML bilan ishlang.':a.mode==='css'?'HTML va CSS bilan ishlang.':'HTML, CSS va JavaScriptni yozing.'} So‘ng natijani ko‘ring. Kod sahifadan ajratilgan o‘quv oynasida ochiladi. ${a.mode==='html'?'Tashqi manzildagi rasmni ko‘rish uchun internet kerak.':a.mode==='css'?'Tashqi resurslar uchun internet kerak. Bootstrap darslarida kutubxona ko‘rish oynasiga avtomatik ulanadi.':'Tashqi rasm, API va kutubxonalar uchun internet kerak.'}</p><div class="frontend-editors"><label>HTML<textarea id="fe-html" class="lab-editor" spellcheck="false" aria-label="HTML kodi"></textarea></label>${a.mode!=='html'?'<label>CSS<textarea id="fe-css" class="lab-editor" spellcheck="false" aria-label="CSS kodi"></textarea></label>':''}${a.mode==='web'?'<label>JavaScript<textarea id="fe-js" class="lab-editor" spellcheck="false" aria-label="JavaScript kodi"></textarea></label>':''}</div><div class="lab-actions"><button class="cta" onclick="runFrontendPreview()">▶ Natijani ko‘rish</button><button class="retry" onclick="stopFrontendPreview()">Ko‘rishni to‘xtatish</button><button class="retry" onclick="setFrontendPreviewWidth('360px')">Mobil 360px</button><button class="retry" onclick="setFrontendPreviewWidth('100%')">To‘liq kenglik</button><button class="retry" onclick="resetFrontendAssignment()">Namuna kodini tiklash</button><button class="retry" onclick="downloadFrontendWork()">HTMLni yuklab olish ↓</button></div><p id="fe-save" role="status">Kod shu brauzerda, ushbu mavzu uchun saqlanadi.</p>${a.mode==='web'?'<p class="muted">Ko‘rish oynasidagi localStorage ushbu darsga ajratilgan o‘quv saqlashi bilan ishlaydi. Haqiqiy origin bilan saqlashni mahalliy loyihada ham sinang.</p>':''}<div id="fe-preview-holder"></div><h3>Konsol va xatolar</h3><pre id="fe-console" class="lab-output">Natija hali ishga tushirilmadi.</pre>`;
 else if(a.mode==='js')panel.innerHTML+=`<label class="lab-label" for="lab-editor">JavaScript kodi</label><textarea id="lab-editor" class="lab-editor" spellcheck="false"></textarea><label for="lab-input">prompt() javoblari — har bir javob yangi qatorda</label><textarea id="lab-input" rows="2"></textarea><div class="lab-actions"><button id="lab-run" class="cta" onclick="runCodingLab(false)">▶ Kodni bajarish</button><button id="lab-stop" class="retry" onclick="stopCodingLab(true)" disabled>To‘xtatish</button><button class="retry" onclick="resetFrontendAssignment()">Namuna kodini tiklash</button><button class="retry" onclick="downloadCodingLab()">Kodni yuklab olish ↓</button></div><p id="lab-draft" class="muted">Kod shu brauzerda saqlanadi.</p><p id="lab-status" role="status">Namuna yoki o‘z kodingizni ishga tushiring.</p><pre id="lab-output" class="lab-output">Natija shu yerda chiqadi.</pre><div id="lab-checks"></div><p class="muted">Bu oyna sinxron JavaScript uchun; bajarish vaqti 2 soniya. DOM va asinxron sahifa misollari tegishli mavzulardagi HTML ish maydonida bajariladi.</p>`;
 else panel.innerHTML+=`<h3>${a.mode==='files'?'Kuzatish va hisobot':'Kompyuteringizda bajariladigan ish'}</h3><p>${a.mode==='files'?(data.number===4?'Konspektdagi papka va fayl amallarini o‘z kompyuteringizda bajaring; natijani matn bilan qayd eting. HTML kodi yozilmaydi.':'Konspektdagi tushunchalarni misol bilan ajrating va xulosani yozing. Terminal buyruqlari keyingi darsda o‘rganiladi.'):'Git buyruqlari ushbu sahifada bajarilmaydi. Ularni o‘zingizga tegishli alohida loyiha papkasidagi terminalda bajaring. Natijani quyidagi hisobotga yozing.'}</p><label for="fe-report">Bajarilgan ish, kuzatilgan natija va xulosa</label><textarea id="fe-report" class="lab-editor" spellcheck="false"></textarea><p id="fe-save" role="status">Hisobot shu brauzerda saqlanadi.</p>`;
 panel.innerHTML+=`<h3>Topshirishdan oldin</h3>${a.criteria.map((x,i)=>`<label class="option"><input type="checkbox" class="fe-checklist" data-index="${i}"> ${frontendEscape(x)}</label>`).join('')}<label for="fe-reflection" class="lab-label">Xulosa: nima ishladi, qaysi xatoni tuzatdingiz?</label><textarea id="fe-reflection" rows="4" style="width:100%;box-sizing:border-box"></textarea><p class="muted">Belgilash — o‘zini tekshirish ro‘yxati. Amaliy ish avtomatik yakuniy baholanmaydi; 10 savolli nazariy test alohida hisoblanadi.</p><button class="cta" onclick="openResource(3)">Test sinoviga o‘tish →</button>`;
 document.querySelector('.article').appendChild(panel);let saved={};try{saved=JSON.parse(localStorage.getItem(frontendDraftKey())||'{}');}catch(e){}
 if(['web','html','css'].includes(a.mode)){document.getElementById('fe-html').value=saved.html??a.code;if(document.getElementById('fe-css'))document.getElementById('fe-css').value=saved.css??'';if(document.getElementById('fe-js'))document.getElementById('fe-js').value=saved.js??'';}else if(a.mode==='js')document.getElementById('lab-editor').value=saved.code??a.code;else document.getElementById('fe-report').value=saved.report??'';
 document.getElementById('fe-reflection').value=saved.reflection??'';panel.querySelectorAll('.fe-checklist').forEach((el,i)=>el.checked=!!saved.checklist?.[i]);
 panel.querySelectorAll('textarea,input').forEach(el=>el.addEventListener('input',saveFrontendAssignment));
}
function frontendWorkSnapshot(){const value=id=>document.getElementById(id)?.value??'';return {html:value('fe-html'),css:value('fe-css'),js:value('fe-js'),code:value('lab-editor'),report:value('fe-report'),reflection:value('fe-reflection'),checklist:[...document.querySelectorAll('.fe-checklist')].map(x=>x.checked)};}
function saveFrontendAssignment(){try{localStorage.setItem(frontendDraftKey(),JSON.stringify(frontendWorkSnapshot()));const status=document.getElementById('fe-save')||document.getElementById('lab-draft');if(status)status.textContent='Shu brauzerda saqlandi. Boshqa qurilmaga avtomatik ko‘chmaydi.';}catch(e){const status=document.getElementById('fe-save')||document.getElementById('lab-draft');if(status)status.textContent='Saqlash mavjud emas. Kodni faylga yuklab oling yoki nusxa saqlang.';}}
function resetFrontendAssignment(){stopCodingLab();stopFrontendPreview();const a=activeData().assignment;if(['web','html','css'].includes(a.mode)){document.getElementById('fe-html').value=a.code;if(document.getElementById('fe-css'))document.getElementById('fe-css').value='';if(document.getElementById('fe-js'))document.getElementById('fe-js').value='';}else if(a.mode==='js')document.getElementById('lab-editor').value=a.code;saveFrontendAssignment();}
function frontendDocument(work,bridge=''){
 const style='<style>'+work.css.replace(/<\/style/gi,'<\\/style')+'</style>';
 const script='<script>'+work.js.replace(/<\/script/gi,'<\\/script')+'<\/script>';
 const bootstrap=currentModule===5&&activeData().assignment?.bootstrap===true?'<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" integrity="sha384-sRIl4kxILFvY47J16cr9ZwB07vP4J8+LH7qKQnuqkuIAvNWLzeN8tE5YBujZqJLB" crossorigin="anonymous"><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js" integrity="sha384-FKyoEForCGlyvwx9Hj09JcYn3nv7wiPVlz7YYwJrWVcXK/BmnVDxM+D2scQbITxI" crossorigin="anonymous"><\/script>':'';
 const head=bridge+'<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">'+bootstrap+style;
 if(/<html\b/i.test(work.html)){
  let result=work.html;
  if(/<head\b[^>]*>/i.test(result))result=result.replace(/<head\b[^>]*>/i,match=>match+head);
  else result=result.replace(/<html\b[^>]*>/i,match=>match+'<head>'+head+'</head>');
  if(/<\/body\s*>/i.test(result))result=result.replace(/<\/body\s*>/i,()=>script+'</body>');else result+=script;
  return result;
 }
 return '<!doctype html><html lang="uz"><head>'+head+'</head><body>'+work.html+script+'</body></html>';
}
function downloadFrontendWork(){const url=URL.createObjectURL(new Blob([frontendDocument(frontendWorkSnapshot())],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='frontend-'+currentLesson+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setFrontendPreviewWidth(width){const frame=document.getElementById('frontend-preview');if(frame)frame.style.width=width;}
function frontendStageError(work,mode){
 if(mode==='html'&&(/<style\b|\sstyle\s*=/i.test(work.html)||work.css.trim()))return 'Bu HTML darsi: avval o‘tilgan HTML teg va atributlari bilan ishlang. CSS 13-mavzudan boshlanadi.';
 if(['html','css'].includes(mode)&&(/<script\b|\son[a-z]+\s*=|javascript\s*:/i.test(work.html)||work.js.trim()))return 'Bu bosqichda JavaScript bajarilmaydi. JavaScript 41-mavzudan o‘rganiladi.';
 return '';
}
function runFrontendPreview(){const work=frontendWorkSnapshot(),error=frontendStageError(work,activeData().assignment.mode);if(error){document.getElementById('fe-console').textContent=error;return;}stopFrontendPreview();saveFrontendAssignment();const frame=document.createElement('iframe');frame.id='frontend-preview';frame.title='Frontend natijasi';frame.setAttribute('sandbox','allow-scripts');frame.referrerPolicy='no-referrer';const consoleBox=document.getElementById('fe-console');consoleBox.textContent='';let count=0;const key=frontendDraftKey()+':preview-storage';let storage={};try{storage=JSON.parse(localStorage.getItem(key)||'{}');}catch(e){}
 const csp=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline' https://cdn.jsdelivr.net; style-src 'unsafe-inline' https:; img-src https: data:; media-src https: data:; font-src https: data:; connect-src https:; form-action 'none'; base-uri 'none';">`;
 const setup=`(()=>{const send=(data)=>parent.postMessage(data,'*');const format=x=>typeof x==='string'?x:(JSON.stringify(x)??String(x));for(const level of ['log','warn','error','info'])console[level]=(...args)=>send({type:'fe-console',line:args.map(format).join(' ')});addEventListener('error',e=>send({type:'fe-console',line:'Xato: '+e.message}));addEventListener('unhandledrejection',e=>send({type:'fe-console',line:'Xato: '+String(e.reason)}));let store=${JSON.stringify(storage).replace(/</g,'\\u003c')};try{Object.defineProperty(window,'localStorage',{value:{getItem:k=>Object.prototype.hasOwnProperty.call(store,String(k))?store[String(k)]:null,setItem:(k,v)=>{store[String(k)]=String(v);send({type:'fe-storage',store});},removeItem:k=>{delete store[String(k)];send({type:'fe-storage',store});},clear:()=>{store={};send({type:'fe-storage',store});},key:i=>Object.keys(store)[i]??null,get length(){return Object.keys(store).length;}}});}catch(e){console.warn('O‘quv saqlashi mavjud emas');}})();`;
 frame.srcdoc=frontendDocument(frontendWorkSnapshot(),csp+'<script>'+setup+'<\/script>');
 frontendPreviewListener=event=>{if(event.source!==frame.contentWindow||!event.data)return;if(event.data.type==='fe-console'&&count++<100){consoleBox.textContent+=(consoleBox.textContent?'\n':'')+String(event.data.line).slice(0,2000);}if(event.data.type==='fe-storage'&&event.data.store&&typeof event.data.store==='object'){try{const text=JSON.stringify(event.data.store);if(text.length<100000)localStorage.setItem(key,text);}catch(e){}}};window.addEventListener('message',frontendPreviewListener);document.getElementById('fe-preview-holder').appendChild(frame);if(!consoleBox.textContent)consoleBox.textContent='Natija yuqoridagi ko‘rish oynasida. Konsol xabarlari bo‘lsa shu yerda ko‘rinadi.';
}
